type AidenLogoLoaderProps = {
  className?: string;
  /** When true, hides from assistive tech (e.g. label is adjacent). */
  decorative?: boolean;
  'aria-label'?: string;
  /**
   * When set: one play on first mount, then replay every N ms while the window stays in the foreground.
   * When the tab/window is hidden the timer is cleared; when you come back (visibility + focus) the
   * animation runs once and a fresh N ms interval starts. Omit for infinite loop (e.g. chat pill).
   */
  playOnceThenEveryMs?: number;
};

export function AidenLogoLoader({
  className,
  decorative,
  'aria-label': ariaLabel,
  playOnceThenEveryMs,
}: AidenLogoLoaderProps) {
  const finite = playOnceThenEveryMs != null && playOnceThenEveryMs > 0;
  const [replayTick, setReplayTick] = useState(0);
  const intervalRef = useRef<number | null>(null);
  const debounceRef = useRef<number | null>(null);
  const allowWakeKickRef = useRef(false);
  const svgRef = useRef<SVGSVGElement>(null);

  // WebKit/Electron: first paint sometimes skips CSS animations on nested SVG <g>.
  useLayoutEffect(() => {
    if (!svgRef.current) return;
    void svgRef.current.getBoundingClientRect();
  }, [finite, replayTick]);

  useEffect(() => {
    if (playOnceThenEveryMs == null || playOnceThenEveryMs <= 0) return;
    const ms = playOnceThenEveryMs;

    const clearArm = () => {
      if (intervalRef.current != null) {
        window.clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };

    const armInterval = () => {
      clearArm();
      intervalRef.current = window.setInterval(() => {
        setReplayTick((n) => n + 1);
      }, ms);
    };

    const kickAndArm = () => {
      clearArm();
      setReplayTick((n) => n + 1);
      armInterval();
    };

    const scheduleWakeKick = () => {
      if (debounceRef.current != null) {
        window.clearTimeout(debounceRef.current);
      }
      debounceRef.current = window.setTimeout(() => {
        debounceRef.current = null;
        if (!allowWakeKickRef.current) return;
        if (document.visibilityState !== 'visible') return;
        kickAndArm();
      }, 120);
    };

    // First entry: initial SVG mount plays once (tick 0); only start the repeating timer.
    armInterval();

    const gateId = window.setTimeout(() => {
      allowWakeKickRef.current = true;
    }, 600);

    const onVisibility = () => {
      if (document.visibilityState === 'hidden') {
        if (debounceRef.current != null) {
          window.clearTimeout(debounceRef.current);
          debounceRef.current = null;
        }
        clearArm();
        return;
      }
      scheduleWakeKick();
    };

    document.addEventListener('visibilitychange', onVisibility);
    window.addEventListener('focus', scheduleWakeKick);

    return () => {
      window.clearTimeout(gateId);
      if (debounceRef.current != null) {
        window.clearTimeout(debounceRef.current);
        debounceRef.current = null;
      }
      document.removeEventListener('visibilitychange', onVisibility);
      window.removeEventListener('focus', scheduleWakeKick);
      clearArm();
    };
  }, [playOnceThenEveryMs]);

  return (
    <span
      className={['aiden-logo-loader', finite && 'aiden-logo-loader--finite', className]
        .filter(Boolean)
        .join(' ')}
      {...(decorative
        ? { 'aria-hidden': true as const }
        : { role: 'img' as const, 'aria-label': ariaLabel ?? 'Aiden' })}
    >
      <svg
        ref={svgRef}
        key={finite ? replayTick : undefined}
        width="1024"
        height="1024"
        viewBox="0 0 1024 1024"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className="size-full max-h-full max-w-full"
        aria-hidden
      >
        <g className="aiden-logo-loader__rotor">
          <g className="aiden-logo-loader__shift aiden-logo-loader__shift--blue">
            <path fillRule="evenodd" clipRule="evenodd" d={PATH_BLUE} fill="#031C60" />
          </g>
          <g className="aiden-logo-loader__shift aiden-logo-loader__shift--cyan">
            <path fillRule="evenodd" clipRule="evenodd" d={PATH_CYAN} fill="#919FFC" />
          </g>
        </g>
      </svg>
    </span>
  );
}
